test('invoiceTotals with discount and VAT works correctly', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 5, unitPrice: 10000, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line 1: total=100000, discount=10000, afterDiscount=90000, VAT=18900
  // Line 2: total=50000, discount=0, afterDiscount=50000, VAT=10500
  // Subtotal=150000, Discount=10000, VAT=29400, Total=150000-10000+29400=169400
  assert.equal(totals.subtotal, 150000);
  assert.equal(totals.discount, 10000);
  assert.equal(totals.vat, 29400);
  assert.equal(totals.total, 169400);
});

