test('invoiceTotals calculates VAT on amount after discount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 10, unitPrice: 8500, vatRate: 21, discountPercent: 10 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // lineTotal = 85000, discount = 8500, amountAfterDiscount = 76500, VAT = 76500 × 21 / 100 = 16065
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 8500);
  assert.equal(totals.vat, 16065);
  assert.equal(totals.total, 85000 - 8500 + 16065);
});

test('invoiceTotals returns vat in the result', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 10, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 17850);
  assert.equal(totals.total, 102850);
});

test('invoiceTotals sums VAT from multiple lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 10, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
      { sku: 'PRINT-A4', qty: 100, unitPrice: 100, vatRate: 9, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line 1: VAT = 85000 × 21 / 100 = 17850
  // Line 2: VAT = 10000 × 9 / 100 = 900
  // Total VAT = 18750
  assert.equal(totals.vat, 18750);
});

test('invoiceTotals handles 0% VAT rate', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'WORKSHOP-DAY', qty: 2, unitPrice: 50000, vatRate: 0, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 100000);
});

test('invoiceTotals rounds VAT per line before summing', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'PRINT-A4', qty: 100, unitPrice: 111, vatRate: 9, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // lineTotal = 11100, VAT = 11100 × 9 / 100 = 999
  assert.equal(totals.vat, 999);
});

test('invoiceTotals with discount and VAT works correctly', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 5, unitPrice: 10000, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line 1: total=100000, discount=10000, afterDiscount=90000, VAT=18900
  // Line 2: total=50000, discount=0, afterDiscount=50000, VAT=10500
  // Subtotal=150000, Discount=10000, VAT=29400, Total=150000-10000+29400=169400
  assert.equal(totals.subtotal, 150000);
  assert.equal(totals.discount, 10000);
  assert.equal(totals.vat, 29400);
  assert.equal(totals.total, 169400);
});

